"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[769],{109:(e,a,o)=>{o.d(a,{A:()=>s});let s=(0,o(4294).A)("Search",[["circle",{cx:"11",cy:"11",r:"8",key:"4ej97u"}],["path",{d:"m21 21-4.3-4.3",key:"1qie3q"}]])},2965:(e,a,o)=>{o.d(a,{Pi:()=>s});let s=[{id:"voice-leading-workout",title:"Voice Leading en ii-V-I",category:"harmony",level:"intermediate",duration:20,goal:"Dominar el movimiento suave entre acordes usando voice leading crom\xe1tico",setup:["Backing track de ii-V-I en C (o cualquier tonalidad)","Metr\xf3nomo a 80 BPM","Conocimiento de arpegios de 7ma"],steps:[{step:1,instruction:"Toca solo las guide tones (3ra y 7ma) de cada acorde",duration:5,tempo:"80 BPM",tips:["Dm7: F (3ra) → C (7ma)","G7: B (3ra) → F (7ma)","Cmaj7: E (3ra) → B (7ma)","Observa: C→B (medio tono), F→F (com\xfan), B→C (medio tono), E→F (medio tono)"]},{step:2,instruction:"A\xf1ade aproximaciones crom\xe1ticas a las guide tones",duration:5,tips:["Dm7: E→F (aprox. crom\xe1tica a 3ra)","G7: Bb→B (aprox. crom\xe1tica a 3ra)","Cmaj7: Eb→E (aprox. crom\xe1tica a 3ra)","Esto crea l\xedneas muy crom\xe1ticas y fluidas"]},{step:3,instruction:"Improvisa enfatizando guide tones en tiempos 1 y 3",duration:10,tips:["Las guide tones SIEMPRE en beats fuertes","Usa aproximaciones en beats d\xe9biles","Conecta con cromatismo o escalas","Gr\xe1bate y verifica que guide tones destacan"]}],progression:"Dm7 - G7 - Cmaj7",evaluation:["\xbfPuedo escuchar claramente los cambios de acordes?","\xbfLas guide tones caen en beats fuertes?","\xbfEl movimiento entre acordes es suave?","\xbfSuena bebop/jazz?"],nextSteps:"Aplica esta t\xe9cnica a standards: Autumn Leaves, All The Things You Are, etc."},{id:"pentatonic-superimposition",title:"Superposici\xf3n de Pentat\xf3nicas",category:"melody",level:"advanced",duration:25,goal:'Crear sonidos outside controlados usando pentat\xf3nicas "incorrectas"',setup:["Backing track de Cmaj7 vamp","Conocimiento de pentat\xf3nicas en todas las posiciones","Metr\xf3nomo opcional: 100 BPM"],steps:[{step:1,instruction:'Toca pentat\xf3nica "correcta": C Mayor (C-D-E-G-A)',duration:5,tips:["Esto es inside - suena bien",'Familiar\xedzate con el sonido "seguro"',"Practica en diferentes posiciones"]},{step:2,instruction:"Ahora D Mayor pentat\xf3nica sobre Cmaj7 (D-E-F#-A-B)",duration:5,tips:["F# es #11 de C - suena Lidio","Esto es inside pero con color sofisticado","Muy usado en jazz moderno"]},{step:3,instruction:"Prueba Db Mayor pentat\xf3nica (Db-Eb-F-Ab-Bb)",duration:5,tips:["TODAS las notas son outside de Cmaj7","Suena super tenso - pero controlado","\xdasalo brevemente, luego resuelve a C Mayor pent"]},{step:4,instruction:"Improvisa alternando: C Mayor pent (inside) → pentat\xf3nica outside → resolve",duration:10,tips:["Formula: 4 beats inside → 2 beats outside → 2 beats resolving","Opciones outside: Db, Eb, F#, Ab Mayor pentat\xf3nicas","SIEMPRE resuelve de vuelta a inside","Esto crea tensi\xf3n y release controlados"]}],progression:"Cmaj7 (vamp)",evaluation:["\xbfPuedo controlar cu\xe1ndo estoy inside vs outside?","\xbfMis resoluciones son claras y musicales?","\xbfUso el outside para crear tensi\xf3n intencional?","\xbfSuena ca\xf3tico o controlado?"],nextSteps:"Aplica esta t\xe9cnica en ii-V-I: usa pentat\xf3nicas outside en V7, resuelve en I"},{id:"rhythmic-displacement",title:"Desplazamiento R\xedtmico",category:"rhythm",level:"intermediate",duration:15,goal:"Crear inter\xe9s r\xedtmico desplazando patrones mel\xf3dicos",setup:["Metr\xf3nomo a 80 BPM con clicks en 2 y 4","Backing track simple de Dm7 vamp","Patr\xf3n mel\xf3dico simple (ej: D-E-F-G)"],steps:[{step:1,instruction:"Toca patr\xf3n D-E-F-G empezando en beat 1",duration:3,tempo:"80 BPM",tips:["Toca en corcheas: D(1) E(&) F(2) G(&)",'Esto est\xe1 "en el beat" - predecible',"Repite hasta que sea natural"]},{step:2,instruction:"Ahora empieza el mismo patr\xf3n en el & de 1",duration:3,tips:["D(&1) E(2) F(&2) G(3)","El patr\xf3n est\xe1 desplazado medio beat","Suena m\xe1s interesante pero es el MISMO patr\xf3n"]},{step:3,instruction:"Var\xeda el punto de inicio: beat 1, &1, 2, &2, 3, &3, 4, &4",duration:5,tips:["Mismo patr\xf3n mel\xf3dico, 8 posiciones r\xedtmicas diferentes","Cada una crea un feeling distinto","Algunos puntos suenan m\xe1s tensos que otros"]},{step:4,instruction:"Improvisa usando desplazamiento intencional",duration:4,tips:["Toca una frase en el beat","Rep\xedtela desplazada","Esto crea conversaci\xf3n interna","T\xe9cnica avanzada: desplazamiento de frases completas"]}],progression:"Dm7 (vamp)",evaluation:["\xbfPuedo mantener el tiempo mientras desplazo?","\xbfEl desplazamiento suena intencional?","\xbfUso el desplazamiento para crear inter\xe9s?"],nextSteps:"Aplica desplazamiento a licks conocidos - los transforma completamente"},{id:"target-note-control",title:"Control de Target Notes",category:"melody",level:"beginner",duration:15,goal:"Colocar chord tones en tiempos fuertes de forma consistente",setup:["Backing track de ii-V-I en cualquier tonalidad","Metr\xf3nomo a 60-80 BPM","Conocimiento de arpegios b\xe1sicos"],steps:[{step:1,instruction:"Identifica las chord tones de cada acorde",duration:2,tips:["Dm7: D-F-A-C","G7: G-B-D-F","Cmaj7: C-E-G-B","Estas son tus targets"]},{step:2,instruction:"Toca solo chord tones en beats 1 y 3",duration:5,tempo:"60 BPM",tips:["Beat 1: chord tone, Beat 3: otra chord tone","Beats 2 y 4: silencio o notas de paso",'Esto garantiza que "suene el acorde"']},{step:3,instruction:"Llena beats 2 y 4 con approach notes o passing tones",duration:4,tips:["Beat 1: D (root), Beat 2: E (approach), Beat 3: F (3rd)",'Las notas "extra" conectan las chord tones',"Pero el peso sigue en 1 y 3"]},{step:4,instruction:"Improvisa con la regla: chord tones en 1 y 3",duration:4,tips:["Libertad total EXCEPTO beats 1 y 3","Ah\xed DEBES tocar chord tones","Esto es la base del bebop"]}],progression:"Dm7 - G7 - Cmaj7",evaluation:["\xbfCada beat 1 y 3 tiene una chord tone?","\xbfSe escucha claramente la progresi\xf3n?","\xbfSuena musical o mec\xe1nico?"],nextSteps:"Cuando domines 1 y 3, intenta colocar guide tones (3ra y 7ma) espec\xedficamente"},{id:"motific-development",title:"Desarrollo Mot\xedvico",category:"melody",level:"intermediate",duration:20,goal:"Desarrollar un motivo simple en un solo completo",setup:["Backing track modal (ej: Dm7 vamp)","Tempo medium: 100-120 BPM",'Mentalidad de "menos es m\xe1s"'],steps:[{step:1,instruction:"Crea un motivo de 3-4 notas simple",duration:2,tips:["Ejemplo: D-E-F-A","DEBE ser memorable y simple","No m\xe1s de 4 notas","Aseg\xfarate que tenga un ritmo interesante"]},{step:2,instruction:"Repite el motivo exactamente 3 veces",duration:3,tips:["Sin cambios - repetici\xf3n literal","Esto establece el motivo en el o\xeddo",'La audiencia ahora "conoce" tu idea']},{step:3,instruction:"Var\xeda el motivo usando estas t\xe9cnicas",duration:10,tips:["Transposici\xf3n: mueve a otra altura (D-E-F-A → A-B-C-E)","Inversi\xf3n: voltea las direcciones (D↑E↑F↑A → D↓C↓Bb↓F)","Aumentaci\xf3n: hazlo m\xe1s lento (corcheas → negras)","Diminuci\xf3n: hazlo m\xe1s r\xe1pido (negras → corcheas)","Fragmentaci\xf3n: usa solo parte del motivo (D-E-F)","Expansi\xf3n: a\xf1ade notas entre las existentes"]},{step:4,instruction:"Improvisa un solo de 2 minutos usando SOLO este motivo y variaciones",duration:5,tips:["No introduzcas nuevo material","Desarrolla el motivo original de todas las formas posibles","Esto es como Sonny Rollins improvisaba"]}],progression:"Dm7 (modal vamp) o cualquier progresi\xf3n simple",evaluation:["\xbfMi solo suena cohesivo?","\xbfPuedo escuchar el motivo original en las variaciones?","\xbfHe desarrollado el material o solo improvis\xe9 random?","\xbfSuena como una historia o conversaci\xf3n?"],nextSteps:"Analiza solos de Sonny Rollins - maestro del desarrollo mot\xedvico"},{id:"call-and-response",title:"Call and Response",category:"integration",level:"beginner",duration:15,goal:"Crear conversaci\xf3n musical entre frases",setup:["Backing track de blues o ii-V-I","Metr\xf3nomo a tempo comfortable",'Mentalidad de "espacio es m\xfasica"'],steps:[{step:1,instruction:"Toca una frase de 2 compases (call)",duration:3,tips:["Mant\xe9n simple - 4-6 notas",'Termina en una nota que "pide" resoluci\xf3n',"No llenes todos los espacios"]},{step:2,instruction:"SILENCIO durante 2 compases",duration:3,tips:["No toques nada","Escucha el silencio",'Piensa qu\xe9 vas a "responder"',"Este espacio es crucial"]},{step:3,instruction:"Toca una respuesta de 2 compases (response)",duration:3,tips:["Debe relacionarse con el call","Puede ser una variaci\xf3n del call","O puede contrastarlo",'Debe sentirse como "respuesta"']},{step:4,instruction:"Practica call-and-response durante 8 chorus",duration:6,tips:["Call (2 bars) → Silencio (2 bars) → Response (2 bars) → Silencio (2 bars)","Esto es blues cl\xe1sico","Graba y escucha si suena conversacional"]}],progression:"Blues en cualquier tonalidad",evaluation:["\xbfDej\xe9 suficiente espacio?","\xbfLas respuestas se relacionan con los calls?","\xbfSuena como una conversaci\xf3n?","\xbfO solo una serie de frases random?"],nextSteps:"Trading 4s con otros m\xfasicos - call and response en tiempo real"},{id:"chromaticism-integration",title:"Integraci\xf3n de Cromatismo",category:"technique",level:"intermediate",duration:20,goal:"Usar cromatismo como herramienta expresiva, no como error",setup:["Backing track de standards (ej: Autumn Leaves)","Tempo medium: 120 BPM","Conocimiento de approach notes"],steps:[{step:1,instruction:"Improvisa solo diat\xf3nico (inside) durante 1 chorus",duration:4,tips:["Solo notas de la escala correspondiente","Sin cromatismo","Establece el centro tonal",'Este es tu "home base"']},{step:2,instruction:"A\xf1ade aproximaciones crom\xe1ticas SOLO a chord tones",duration:5,tips:["Approach desde medio tono arriba o abajo","Target siempre una chord tone","El cromatismo es intencional, no random","Ejemplo: Eb→E (3ra de Cmaj7)"]},{step:3,instruction:"Usa enclosures crom\xe1ticos en beats d\xe9biles",duration:5,tips:["Beat 1: chord tone, Beat &1-2: enclosure, Beat &2: target","G(1) → Ab-F#(enclosure) → G(3)","Esto mantiene el centro pero a\xf1ade color"]},{step:4,instruction:"Improvisa integrando todas las t\xe9cnicas crom\xe1ticas",duration:6,tips:["Base diat\xf3nica + aproximaciones + enclosures + passing chromaticism","El cromatismo embellece, no reemplaza la base arm\xf3nica","Siempre resuelve a inside","Gr\xe1bate: debe sonar jazz, no ca\xf3tico"]}],progression:"Autumn Leaves o cualquier standard",evaluation:["\xbfEl cromatismo suena intencional?","\xbfMantengo el centro tonal?","\xbfResuelvo las tensiones crom\xe1ticas?","\xbfSuena bebop/jazz profesional?"],nextSteps:"Transcribe 8 compases de Charlie Parker - analiza su uso de cromatismo"},{id:"blues-mixing",title:"Mezcla Blues-Jazz",category:"integration",level:"intermediate",duration:20,goal:"Combinar vocabulario blues con vocabulario bebop",setup:["Backing track de blues en F","Tempo medium swing: 120-140 BPM","Conocimiento de pentat\xf3nica blues y bebop scales"],steps:[{step:1,instruction:"Primer chorus: solo F blues pentat\xf3nica",duration:4,tips:["F-Ab-Bb-Cb-C-Eb","Enfatiza la blue note (Cb/B)","Bends y vibrato","Este es puro blues"]},{step:2,instruction:"Segundo chorus: cambios espec\xedficos (F7, Bb7, C7)",duration:4,tips:["F7: F mixolidio o bebop dom","Bb7: Bb mixolidio","C7: C mixolidio o alterado","Esto es puro jazz"]},{step:3,instruction:"Tercer chorus: MEZCLA ambos approaches",duration:5,tips:["Compases 1-4: blues pentat\xf3nica","Compases 5-6 (cambio a Bb7): bebop scales","Compases 7-8: blues de nuevo","Compases 9-10 (turnaround): jazz changes","Compases 11-12: blues"]},{step:4,instruction:"Improvisa 5 chorus mezclando libremente",duration:7,tips:["No hay reglas - mezcla seg\xfan sientas",'Alterna entre "sentir blues" y "cambios jazz"',"Esto es lo que hacen Grant Green, Kenny Burrell","Graba y escucha: debe sonar org\xe1nico, no forzado"]}],progression:"Blues en F (o cualquier tonalidad)",evaluation:["\xbfPuedo alternar entre blues y jazz fluidamente?","\xbfAmbos vocabularios se sienten naturales?","\xbfLa mezcla suena cohesiva o desarticulada?"],nextSteps:'Escucha "Blues for Alice" de Charlie Parker - blueprint perfecto'},{id:"dynamics-expression",title:"Din\xe1mica y Expresi\xf3n",category:"integration",level:"beginner",duration:15,goal:"Usar volumen y articulaci\xf3n como herramientas expresivas",setup:["Backing track de balada","Sin metr\xf3nomo - timing flexible",'Mentalidad de "cantar con el instrumento"'],steps:[{step:1,instruction:"Improvisa un chorus en fortissimo (muy fuerte)",duration:3,tips:["M\xe1ximo volumen en todas las notas","Escucha c\xf3mo suena","Probablemente agresivo, sin matices"]},{step:2,instruction:"Ahora en pianissimo (muy suave)",duration:3,tips:["M\xednimo volumen","\xcdntimo y delicado","Probablemente mon\xf3tono si todo es igual"]},{step:3,instruction:"Improvisa con M\xc1XIMO rango din\xe1mico",duration:5,tips:["Empieza pp, crece a ff, baja a pp","Usa crescendos y decrescendos dentro de frases","Notas individuales: variar volumen","Esto crea drama y emoci\xf3n"]},{step:4,instruction:"A\xf1ade articulaci\xf3n variada",duration:4,tips:["Legato (suave y conectado)","Staccato (corto y separado)","Acentos en notas espec\xedficas","Vibrato en notas largas","Combina con din\xe1mica para m\xe1xima expresi\xf3n"]}],progression:"Balada lenta (ej: Body and Soul, Misty)",evaluation:["\xbfUso el rango din\xe1mico completo?","\xbfVar\xeda mi articulaci\xf3n?","\xbfSuena m\xe1s expresivo que antes?","\xbfTransmito emoci\xf3n?"],nextSteps:"Escucha baladas de Bill Evans - maestro de din\xe1mica y touch"},{id:"metric-modulation",title:"Modulaci\xf3n M\xe9trica",category:"rhythm",level:"advanced",duration:25,goal:"Dominar cambios de tempo percibido manteniendo el pulso constante",setup:["Metr\xf3nomo a 120 BPM con subdivision visual","Grabadora para an\xe1lisis","Comprensi\xf3n s\xf3lida de subdivisiones (corcheas, tresillos, semicorcheas)"],steps:[{step:1,instruction:"Establece el tempo base en corcheas a 120 BPM",duration:5,tempo:"120 BPM",tips:["Toca frases en corcheas regulares","Siente el pulse de negra = 120",'Este es tu tempo "home base"',"Mant\xe9n esto estable durante 2 minutos"]},{step:2,instruction:"Cambia a tresillos, luego haz que el tresillo = nueva corchea",duration:8,tips:["Paso 1: Toca tresillos a 120 BPM","Paso 2: Ahora cada TRESILLO es una nueva corchea","Resultado: has pasado a 180 BPM sin cambiar el metr\xf3nomo","Formula: 120 \xd7 (3/2) = 180","Practica el switch: corcheas → tresillos → nueva velocidad"]},{step:3,instruction:"Modula de semicorcheas a corcheas",duration:7,tips:["Toca semicorcheas a 120 BPM","Ahora cada SEMICORCHEA = nueva corchea","Has pasado a 240 BPM (120 \xd7 2)",'Esto crea sensaci\xf3n de "doble tiempo"',"Luego vuelve al tempo original"]},{step:4,instruction:"Improvisa usando modulaci\xf3n m\xe9trica como herramienta expresiva",duration:5,tips:["Empieza a tempo normal","Modula a tempo m\xe1s r\xe1pido en momentos de tensi\xf3n","Vuelve al tempo original para resoluci\xf3n","Esto es usado por Pat Metheny, Chick Corea","Debe sentirse intencional, no como perder el tiempo"]}],progression:"Cualquier progresi\xf3n modal o vamp",evaluation:["\xbfPuedo mantener el pulse original mientras modulo?","\xbfLas modulaciones son limpias y precisas?","\xbfUso la modulaci\xf3n musicalmente, no solo t\xe9cnicamente?","\xbfPuedo volver al tempo original sin perdida?"],nextSteps:'Estudia "The Unity Band" de Pat Metheny - maestro de modulaci\xf3n m\xe9trica'},{id:"reharmonization-real-time",title:"Reharmonizaci\xf3n en Tiempo Real",category:"harmony",level:"advanced",duration:30,goal:"Crear reharmonizaciones instant\xe1neas mientras improvises",setup:["Backing track de standard conocido (ej: All The Things You Are)","Tempo medium: 140 BPM","Conocimiento profundo de sustituciones tritono y acordes secundarios"],steps:[{step:1,instruction:"Improvisa 1 chorus tocando los cambios originales exactamente",duration:5,tips:["Sigue la armon\xeda del standard","Toca guide tones para confirmar armon\xeda","Este es tu punto de referencia",'Debe sonar "correcto" y familiar']},{step:2,instruction:"Sustituye SOLO dominantes con tritone subs",duration:7,tips:["Cada V7 → bII7 (tritone substitute)","Ejemplo: G7 → Db7 sobre Cmaj7","Toca las guide tones del sustituto","Tu o\xeddo debe ajustarse a la nueva armon\xeda","Mantenlo consistente durante todo el chorus"]},{step:3,instruction:"A\xf1ade acordes secundarios (dominantes secundarios)",duration:8,tips:["Antes de cada acorde, a\xf1ade su V7","Ejemplo: Cmaj7 → Gmaj7 se convierte en Cmaj7 → D7 → Gmaj7",'Esto "crea" cambios extras',"Combina con tritone subs para m\xe1xima densidad arm\xf3nica","Formula: cualquier acorde puede ser precedido por su V7"]},{step:4,instruction:"Improvisa reharmonizando libremente en tiempo real",duration:10,tips:["Usa todas las herramientas: tritone subs, secundarios, acordes passing","Reharmoniza diferente cada vez que pasa la progresi\xf3n","Mant\xe9n la estructura del standard pero cambia armon\xeda","Esto es nivel avanzado de Bill Evans, Herbie Hancock","Graba: debe sonar coherente, no ca\xf3tico"]}],progression:"Any standard jazz (All The Things, Stella, Cherokee)",evaluation:["\xbfMis reharmonizaciones son consistentes?","\xbfSuena m\xe1s interesante que los cambios originales?","\xbfMantengo la estructura del tune?","\xbfLas sustituciones son musicales y l\xf3gicas?"],nextSteps:'Transcribe reharmonizaciones de Bill Evans en "Waltz for Debby" album'},{id:"multi-octave-sequences",title:"Secuencias Multi-Octava",category:"melody",level:"advanced",duration:25,goal:"Crear l\xedneas que abarquen todo el rango del instrumento fluidamente",setup:["Backing track de ii-V-I en varias tonalidades","Tempo medium: 140 BPM","Conocimiento del diapas\xf3n en todas las posiciones"],steps:[{step:1,instruction:"Toca un arpegio de Dm7 en 3 octavas ascendente",duration:5,tips:["Empieza desde el D m\xe1s grave posible","Sube hasta el D m\xe1s agudo","Mant\xe9n el timing uniforme","Debes conocer las digitaciones en todas las posiciones","Practica en todas las tonalidades"]},{step:2,instruction:"Crea secuencias que crucen octavas usando patrones",duration:8,tips:["Patr\xf3n: toca 4 notas arriba, salta octava abajo, repite","Ejemplo: D-F-A-C (octava 1) → D-F-A-C (octava 2) → D-F-A-C (octava 3)","Otro patr\xf3n: zigzag entre octavas","Esto crea textura rica y movimiento dram\xe1tico","Usado extensivamente por Michael Brecker"]},{step:3,instruction:'Practica "registral expansion" - expansi\xf3n de registro',duration:7,tips:["Empieza en registro medio","Cada frase va ligeramente m\xe1s aguda o m\xe1s grave","Construye tensi\xf3n subiendo de registro","Resuelve bajando al registro c\xf3modo","Crea arco dram\xe1tico en el solo"]},{step:4,instruction:"Improvisa usando todo el rango del instrumento",duration:5,tips:["No te quedes en registro c\xf3modo","Usa saltos grandes (intervalos de 9na, 10ma, 11va)","Alterna entre registros como herramienta expresiva","Registro grave = peso, registro agudo = tensi\xf3n","Debe sonar intencional, no como ejercicio"]}],progression:"ii-V-I en m\xfaltiples tonalidades",evaluation:["\xbfUso todo el rango de mi instrumento?","\xbfLos cambios de registro son limpios?","\xbfSuena musical o como ejercicio t\xe9cnico?","\xbfLos saltos de octava tienen prop\xf3sito expresivo?"],nextSteps:"Transcribe solos de Michael Brecker - maestro del rango extendido"},{id:"harmonic-transcription",title:"Transcripci\xf3n Arm\xf3nica",category:"ear",level:"advanced",duration:30,goal:"Transcribir progresiones complejas con sustituciones y reharmonizaciones",setup:["Grabaci\xf3n de standard con reharmonizaci\xf3n (Bill Evans, Brad Mehldau)","Instrumento","Software para loop/slow down (opcional)","Papel pentagramado o app de notaci\xf3n"],steps:[{step:1,instruction:"Escucha la grabaci\xf3n completa 5 veces sin instrumento",duration:8,tips:["Solo escucha - no analices todav\xeda","Identifica la forma del tune","\xbfReconoces el standard original?","\xbfQu\xe9 est\xe1 diferente arm\xf3nicamente?","Toma notas mentales de momentos interesantes"]},{step:2,instruction:"Identifica la funci\xf3n arm\xf3nica de cada acorde",duration:10,tips:["No te preocupes por voicings a\xfan","Identifica: I, ii, V, etc.","\xbfD\xf3nde hay sustituciones tritono?","\xbfHay acordes secundarios no originales?","Trabaja secci\xf3n por secci\xf3n (4 compases)","Usa loop para secciones dif\xedciles"]},{step:3,instruction:"Determina las extensiones y alteraciones",duration:7,tips:["Ya sabes la funci\xf3n, ahora las tensiones","\xbfEs maj7, 7, 6, sus?","\xbfQu\xe9 extensiones? 9, #11, 13?","\xbfHay alteraciones? b9, #9, b13?","Toca junto con la grabaci\xf3n para confirmar","Si no est\xe1s 100% seguro, escribe opciones"]},{step:4,instruction:"Toca la progresi\xf3n completa junto con la grabaci\xf3n",duration:5,tips:["Debe sonar en sincron\xeda perfecta","Si hay clash, revisa tu an\xe1lisis",'Verifica secciones que sonaban "raras"',"Este proceso desarrolla o\xeddo arm\xf3nico avanzado"]}],progression:"Grabaci\xf3n espec\xedfica a transcribir",evaluation:["\xbfPuedo tocar los cambios exactos de la grabaci\xf3n?","\xbfIdentifiqu\xe9 las reharmonizaciones correctamente?","\xbfMi transcripci\xf3n suena igual que el original?","\xbfEntiendo POR QU\xc9 eligieron esas armon\xedas?"],nextSteps:"Aplica esas reharmonizaciones a otros standards - traslada conceptos"},{id:"position-mastery",title:"Dominio Posicional Completo",category:"technique",level:"advanced",duration:30,goal:"Tocar cualquier concepto en cualquier posici\xf3n del instrumento",setup:["Backing track de standard medium tempo","Metr\xf3nomo","Mentalidad de exploraci\xf3n sistem\xe1tica"],steps:[{step:1,instruction:"Divide el diapas\xf3n en 7 posiciones (guitarristas) o rangos (otros)",duration:5,tips:["Posici\xf3n 1: trastes 0-4 (o rango grave)","Posici\xf3n 2: trastes 3-7","Etc., hasta cubrir todo el instrumento","Cada posici\xf3n tiene sus propios shapes y digitaciones","Esto es fundamental para libertad total"]},{step:2,instruction:"Improvisa 1 chorus COMPLETO en Posici\xf3n 1 SOLAMENTE",duration:4,tips:["NO salgas de esa posici\xf3n","Encuentra todos los cambios dentro de esa \xe1rea","Esto fuerza creatividad dentro de l\xedmites","Descubrir\xe1s digitaciones nuevas","Debe sonar musical, no limitado"]},{step:3,instruction:"Repite para cada posici\xf3n (7 chorus total)",duration:15,tips:["1 chorus por posici\xf3n",'Cada posici\xf3n tiene su propio "sabor"',"Posiciones agudas: tensi\xf3n","Posiciones graves: peso","Posiciones medias: balance","Al final conocer\xe1s TODAS las opciones en TODO el diapas\xf3n"]},{step:4,instruction:"Improvisa sin restricciones - usa TODO el diapas\xf3n libremente",duration:6,tips:["Ahora puedes moverte entre posiciones fluidamente","Cada nota tiene m\xfaltiples ubicaciones - eliges la mejor","Esto es libertad total","Tu solo ser\xe1 m\xe1s variado y expresivo","Esta es la diferencia entre intermedios y avanzados"]}],progression:"Cualquier standard jazz",evaluation:["\xbfPuedo tocar fluidamente en TODAS las posiciones?","\xbfConozco m\xfaltiples opciones para cada nota?","\xbfMe muevo entre posiciones sin pensarlo?","\xbfMi elecci\xf3n de posici\xf3n es intencional y musical?"],nextSteps:"Practica esto con TODOS tus standards hasta que sea autom\xe1tico"},{id:"style-fusion",title:"Fusi\xf3n de Estilos",category:"integration",level:"advanced",duration:30,goal:"Combinar vocabularios de diferentes eras y estilos en un solo cohesivo",setup:["Backing track vers\xe1til (ej: blues, modal tune, o standard)","Tempo flexible: 100-140 BPM","Conocimiento de swing, bebop, modal, fusion, contemporary"],steps:[{step:1,instruction:"Improvisa 1 chorus en estilo swing/bebop (a\xf1os 40-50)",duration:5,tips:["Vocabulario de Charlie Parker, Dizzy Gillespie","L\xedneas de 8vos con cromatismo","Guide tones en beats fuertes","Approach notes y enclosures","Debe sonar cl\xe1sico y tradicional"]},{step:2,instruction:"Improvisa 1 chorus en estilo modal (a\xf1os 60)",duration:5,tips:["Vocabulario de John Coltrane, Wayne Shorter","Menos cambios, m\xe1s exploraci\xf3n de escala","Patterns secuenciales","Sheets of sound","Debe sonar espacioso y exploratorio"]},{step:3,instruction:"Improvisa 1 chorus en estilo fusion/contemporary (a\xf1os 70-presente)",duration:5,tips:["Vocabulario de Pat Metheny, Mike Stern","Pentat\xf3nicas superpuestas","Ritmos m\xe1s rock/funk","T\xe9cnicas outside controladas","Debe sonar moderno y fresco"]},{step:4,instruction:"Improvisa fusionando TODOS los estilos en un solo",duration:15,tips:["Secci\xf3n A: bebop tradicional","Secci\xf3n B: modal spaces","Bridge: fusion techniques","\xdaltimo A: mezcla todo","Transiciones deben ser org\xe1nicas","Esto es tu PROPIA VOZ - s\xedntesis de influencias","Ejemplos: Kurt Rosenwinkel, Jonathan Kreisberg","Graba: debe sonar cohesivo, no esquizofr\xe9nico"]}],progression:"Tune vers\xe1til que permita diferentes approaches",evaluation:["\xbfPuedo acceder a diferentes vocabularios fluidamente?","\xbfLas transiciones entre estilos son musicales?","\xbfSuena como MI voz o como copiar estilos?","\xbfHe sintetizado influencias en algo personal?"],nextSteps:"Este es el nivel profesional - sigue desarrollando TU sonido \xfanico"},{id:"polyrhythmic-independence",title:"Independencia Polirr\xedtmica",category:"rhythm",level:"advanced",duration:25,goal:"Tocar l\xedneas que implican diferentes m\xe9tricas simult\xe1neamente",setup:["Metr\xf3nomo a 90 BPM en 4/4","Backing track simple o drone","Comprensi\xf3n de grupos irregulares"],steps:[{step:1,instruction:"Toca grupos de 3 contra el pulso de 4",duration:7,tempo:"90 BPM",tips:["Metr\xf3nomo en 4/4, t\xfa tocas grupos de 3 notas","Resultado: poliritmo 3:4","Las notas caer\xe1n en lugares diferentes cada ciclo","Ejemplo: D-E-F | G-A-Bb | C-D-E (3 notas cada grupo)","Mant\xe9n los grupos de 3 uniformes sin acelerar","Graba: debe sonar deliberado, no como error de timing"]},{step:2,instruction:"Grupos de 5 contra pulso de 4",duration:7,tips:["A\xfan m\xe1s desafiante: 5:4 polyrhythm","Metr\xf3nomo en 4/4, t\xfa en grupos de 5","Se resolver\xe1 cada 20 beats (LCM de 4 y 5)","Usado extensivamente en m\xfasica india y jazz contempor\xe1neo","No aceleres - mant\xe9n los quintolets uniformes"]},{step:3,instruction:"Alterna entre diferentes agrupaciones en la misma frase",duration:6,tips:["Comp\xe1s 1: grupos de 3","Comp\xe1s 2: grupos de 5","Comp\xe1s 3: grupos de 7","Comp\xe1s 4: vuelve a 4/4 regular","Esto crea textura r\xedtmica compleja","Ejemplo: Tigran Hamasyan, Mark Giuliana"]},{step:4,instruction:"Improvisa usando poliritmos como herramienta compositiva",duration:5,tips:["Usa poliritmos en momentos de alta tensi\xf3n","Resuelve volviendo a tiempo regular","Combina con cromatismo para m\xe1ximo effect","Debe sonar intencional y musical","Graba y analiza: \xbfsuena vanguardista o ca\xf3tico?"]}],progression:"Modal vamp o drone",evaluation:["\xbfMantengo el pulso base mientras toco poliritmos?","\xbfLas agrupaciones son uniformes?","\xbfSuena como herramienta musical o error?","\xbfPuedo volver a tiempo regular sin problemas?"],nextSteps:"Estudia m\xfasica de Tigran Hamasyan y Meshuggah para poliritmos extremos"},{id:"upper-structure-triads",title:"Upper Structure Triads en Improvisaci\xf3n",category:"harmony",level:"advanced",duration:25,goal:"Usar tr\xedadas sobre acordes para crear tensiones sofisticadas",setup:["Backing track de ii-V-I","Tempo medium: 120 BPM","Conocimiento s\xf3lido de tr\xedadas en todas las inversiones"],steps:[{step:1,instruction:"Identifica upper structures disponibles para cada acorde",duration:7,tips:["Sobre Dm7: toca tr\xedada de F Mayor (F-A-C) = R-3-5 del acorde","Sobre G7: toca tr\xedada de Db Mayor (Db-F-Ab) = b5-7-b9","Sobre Cmaj7: toca tr\xedada de E menor (E-G-B) = 3-5-7","Cada tr\xedada crea un color espec\xedfico","No todas las tr\xedadas funcionan - elige conscientemente"]},{step:2,instruction:"Practica tr\xedadas sobre G7 alterado",duration:8,tips:["G7alt puede usar: Db Mayor, Eb Mayor, Ab Mayor triads","Db triad = b5-7-b9","Eb triad = b13-b9-#9","Ab triad = b9-3-b13","Toca estas tr\xedadas en todas las inversiones","Suenan super tensos y modernos","Esto es lo que toca Brad Mehldau, Aaron Parks"]},{step:3,instruction:"Improvisa usando upper structures como bloques sonoros",duration:6,tips:["No pienses nota por nota - piensa tr\xedadas completas","Ejemplo: sobre G7alt toca Db triad completo r\xe1pido","Crea frases usando arpegios de estas tr\xedadas","Combina con aproximaciones crom\xe1ticas","Resultado: sonido denso y contempor\xe1neo"]},{step:4,instruction:"Integra en standards - compara con approach tradicional",duration:4,tips:["Chorus 1: improvisa tradicionalmente","Chorus 2: usa solo upper structure triads","\xbfEscuchas la diferencia de color?","Esto es sonido de jazz contempor\xe1neo","Graba ambos - el contraste debe ser obvio"]}],progression:"ii-V-I en m\xfaltiples tonalidades",evaluation:["\xbfPuedo ejecutar upper structures fluidamente?","\xbfSuena m\xe1s contempor\xe1neo que approach tradicional?","\xbfMantengo claridad arm\xf3nica?","\xbfEl color arm\xf3nico es intencional?"],nextSteps:"Transcribe solos de Brad Mehldau - maestro de upper structures"},{id:"extended-voice-leading",title:"Voice Leading con Extensiones",category:"harmony",level:"advanced",duration:30,goal:"Crear l\xedneas con 9nas, 11nas y 13ras como parte del voice leading",setup:["Backing track de standard complejo (Giant Steps, Countdown)","Tempo: 140-180 BPM","Conocimiento de extensiones disponibles por tipo de acorde"],steps:[{step:1,instruction:"Mapea extensiones disponibles para cada acorde del standard",duration:8,tips:["maj7: 9, #11, 13 (avoid 11 natural)","m7: 9, 11, 13","7 (dominante): 9, b9, #9, 11, #11, b13, 13","m7b5: 9, 11, b13","dim7: 9, 11, b13","Escribe esto para cada acorde del tune"]},{step:2,instruction:"Practica voice leading conectando 9nas entre acordes",duration:7,tips:["Dm9 (E) → G9 (A) - movimiento de tono entero","G9 (A) → Cmaj9 (D) - cuarta ascendente","Las 9nas crean l\xednea superior fluida","Toca solo las 9nas mientras backing track toca acordes","Esto es voice leading de nivel superior"]},{step:3,instruction:"Incorpora 11nas y 13ras en el voice leading",duration:8,tips:["Ahora tienes 3+ notas por acorde (3, 7, 9, 11/13)","Construye l\xedneas usando todas estas tensiones","Ejemplo sobre Dm7: D-F-A-C-E-G","Luego a G7: conecta suavemente a G-B-D-F-A-C-E","Cada extensi\xf3n es un target note potencial","Esto crea l\xedneas super sofisticadas"]},{step:4,instruction:"Improvisa usando extensiones como part del vocabulario normal",duration:7,tips:['Las extensiones ya no son "extras" - son core vocabulary',"Target 9nas y 13ras tanto como 3ras y 7mas","Crea frases que enfatizan color arm\xf3nico","Esto es sonido post-bop: McCoy Tyner, Herbie Hancock",'Debe sonar natural, no forzado o "colorful for the sake of it"']}],progression:"Standard complejo con cambios r\xe1pidos",evaluation:["\xbfIncorporo extensiones naturalmente?","\xbfEl voice leading es suave incluyendo extensiones?","\xbfSuena m\xe1s sofisticado que solo triads/7th chords?","\xbfMantengo claridad arm\xf3nica con tensiones a\xf1adidas?"],nextSteps:"Analiza voicings de McCoy Tyner - extensiones como foundation"},{id:"melodic-cell-development",title:"Desarrollo de C\xe9lulas Mel\xf3dicas",category:"melody",level:"advanced",duration:25,goal:"Crear arquitectura mel\xf3dica coherente usando c\xe9lulas de 2-3 notas",setup:["Backing track simple (blues, modal)","Tempo flexible: 100-140 BPM","Mentalidad compositiva, no solo improvisativa"],steps:[{step:1,instruction:"Crea 3 c\xe9lulas mel\xf3dicas \xfanicas de 2-3 notas",duration:5,tips:["C\xe9lula A: intervalo de 3ra (D-F)","C\xe9lula B: intervalo de 4ta (G-C)","C\xe9lula C: intervalo de 2da (E-F)","DEBEN ser simples y reconocibles","Cada una tiene personalidad distinta","Practica cada una hasta memorizarla"]},{step:2,instruction:"Construye frases combinando c\xe9lulas en diferentes \xf3rdenes",duration:8,tips:["A-B-A: crea simetr\xeda","A-B-C: desarrollo lineal","C-A-B-A: estructura compleja","Las c\xe9lulas son LEGO pieces - construye arquitecturas","No agregues material nuevo todav\xeda","Ejemplo: Joe Henderson usaba este approach"]},{step:3,instruction:"Var\xeda las c\xe9lulas usando t\xe9cnicas de desarrollo",duration:7,tips:["Transposici\xf3n: A en diferentes alturas","Inversi\xf3n: D-F se vuelve F-D (descendente)","Expansi\xf3n: D-F se vuelve D-E-F","Contracci\xf3n r\xedtmica: c\xe9lulas m\xe1s r\xe1pidas","Expansi\xf3n r\xedtmica: c\xe9lulas m\xe1s lentas","Secuenciaci\xf3n: repite c\xe9lula subiendo/bajando",'Cada variaci\xf3n mantiene "DNA" de c\xe9lula original']},{step:4,instruction:"Improvisa solo completo usando \xfanicamente estas 3 c\xe9lulas",duration:5,tips:["Debe sonar como composici\xf3n, no ejercicio","Usa las c\xe9lulas y sus variaciones exclusivamente","Esto crea unidad tem\xe1tica extrema","Es como escribir una composici\xf3n en tiempo real","Ejemplos: Steve Coleman, Mark Turner","Graba: debe tener narrativa clara y cohesi\xf3n"]}],progression:"Modal vamp o blues",evaluation:["\xbfMi solo tiene unidad tem\xe1tica?","\xbfPuedo escuchar las c\xe9lulas originales en variaciones?","\xbfSuena compositivo vs random improvisation?","\xbfHe creado una arquitectura mel\xf3dica clara?"],nextSteps:'Estudia "Inner Urge" de Joe Henderson - blueprint de desarrollo celular'},{id:"contrafact-composition",title:"Composici\xf3n de Contrafacts en Tiempo Real",category:"melody",level:"advanced",duration:30,goal:"Crear nuevas melod\xedas sobre progresiones conocidas improvisando",setup:["Backing track de standard conocido (Rhythm Changes, blues)","Tempo medium: 140-180 BPM","Mentalidad: componer, no solo improvisar"],steps:[{step:1,instruction:"Elige un standard y toca su melod\xeda original",duration:3,tips:['Ejemplo: "I Got Rhythm" (Rhythm Changes)',"Familiar\xedzate con la estructura mel\xf3dica","Observa puntos de tensi\xf3n y resoluci\xf3n",'Nota d\xf3nde la melod\xeda "respira"']},{step:2,instruction:"Crea nueva melod\xeda usando los mismos puntos de reposo",duration:10,tips:["Mant\xe9n la estructura de frases: pregunta-respuesta","Los puntos de llegada deben coincidir (cadencias)","Pero el camino es completamente nuevo","Esto es un contrafact - nueva melod\xeda sobre cambios existentes",'Ejemplos hist\xf3ricos: "Anthropology" sobre Rhythm Changes',"Graba tu melod\xeda y rep\xedtela - debe ser memorable"]},{step:3,instruction:'Refina tu contrafact - hazlo "cantable"',duration:8,tips:["Una buena melod\xeda debe poder ser cantada","Simplifica saltos complejos","Crea balance entre pasos y saltos","A\xf1ade motivos repetibles","Ajusta ritmo para que sea memorable","Toca tu melod\xeda sin backing track - debe funcionar sola"]},{step:4,instruction:"Improvisa sobre tu contrafact como si fuera un standard",duration:9,tips:["Toca tu melod\xeda, luego improvisa chorus",'Tu melod\xeda se convierte en el "tema"',"Improvisa sobre los cambios originales","Referencia motivos de tu nueva melod\xeda en el solo","Esto es composici\xf3n instant\xe1nea nivel avanzado","Has creado un nuevo tune en 30 minutos"]}],progression:"Rhythm Changes, Blues, o cualquier standard conocido",evaluation:["\xbfMi contrafact es memorable y cantable?","\xbfFunciona sobre los cambios arm\xf3nicos?","\xbfTiene estructura clara (A-A-B-A, etc.)?","\xbfPodr\xeda ser un standard por derecho propio?"],nextSteps:"Escribe tus mejores contrafacts - podr\xedan ser tus composiciones originales"},{id:"harmonic-rhythm-manipulation",title:"Manipulaci\xf3n del Ritmo Arm\xf3nico",category:"integration",level:"advanced",duration:25,goal:"Crear o eliminar cambios de acordes en tiempo real mientras improvises",setup:["Backing track de standard medium-tempo","Conocimiento profundo de la progresi\xf3n","Capacidad de implicar armon\xeda sin backing track"],steps:[{step:1,instruction:"Improvisa siguiendo ritmo arm\xf3nico exacto del standard",duration:5,tips:["Si el tune cambia cada 2 beats, t\xfa tambi\xe9n",'Esto establece el ritmo arm\xf3nico "correcto"',"Tu l\xednea debe hacer obvios los cambios","Base para manipulaci\xf3n posterior"]},{step:2,instruction:"Alarga acordes - haz que duren el doble",duration:7,tips:["Si standard dice: Dm7 (2 beats) G7 (2 beats)","T\xfa tocas: Dm7 (4 beats) y omites G7 temporalmente","O viceversa: omite Dm7, enfatiza G7","Esto cambia el flow arm\xf3nico","Crea anticipaci\xf3n cuando finalmente cambias","T\xe9cnica avanzada de Keith Jarrett"]},{step:3,instruction:"A\xf1ade acordes extra (double-time harmony)",duration:7,tips:["Standard: Dm7 (4 beats) → G7 (4 beats)","T\xfa: Dm7 (2) → Em7b5 (2) → G7 (2) → Db7 (2)","Has doblado el ritmo arm\xf3nico","Crea densidad y movimiento","Debe sonar intencional, no confuso","Backing track mantiene original - t\xfa creas nueva capa"]},{step:4,instruction:"Improvisa alternando entre ritmo arm\xf3nico expandido y contra\xeddo",duration:6,tips:["Secci\xf3n A: alarga acordes (m\xe1s espacioso)","Secci\xf3n B: a\xf1ade cambios (m\xe1s denso)","Esto es manipulaci\xf3n arquitect\xf3nica del solo","Controlas tensi\xf3n y release a trav\xe9s del ritmo arm\xf3nico","Nivel de libertad m\xe1ximo",'Graba con backing track - debe funcionar aunque no "coincida"']}],progression:"Standard con estructura clara",evaluation:["\xbfMantengo claridad mientras manipulo armon\xeda?","\xbfLas manipulaciones crean inter\xe9s musical?","\xbfPuedo volver al ritmo arm\xf3nico original fluidamente?","\xbfSuena como libertad controlada vs caos?"],nextSteps:"Estudia grabaciones de Keith Jarrett solo - master de manipulaci\xf3n arm\xf3nica"},{id:"scale-three-notes-per-string",title:"Escalas: 3 Notas Por Cuerda",category:"technique",level:"intermediate",duration:20,goal:"Dominar patrones de 3 notas por cuerda en todas las escalas para velocidad y fluidez",setup:["Metr\xf3nomo empezando a 60 BPM","Una escala de 7 notas (ej: C Mayor, D D\xf3rico, G Mixolidio)","Conocimiento de posiciones del diapas\xf3n"],steps:[{step:1,instruction:"Aprende el patr\xf3n de 3 notas por cuerda de la escala elegida",duration:5,tempo:"60 BPM",tips:["C Mayor: E string (8-10-12), A string (7-9-10), D string (7-9-10), etc.","Distribuye las 7 notas en grupos de 3-3-1 o 3-4","Usa digitaci\xf3n: \xedndice-medio-me\xf1ique o \xedndice-anular-me\xf1ique","Practica ascendente primero: E→A→D→G→B→E","Mant\xe9n la mano relajada, evita tensi\xf3n"]},{step:2,instruction:"Practica descendente",duration:5,tempo:"60-80 BPM",tips:["Mismo patr\xf3n pero bajando","La digitaci\xf3n inversa puede ser me\xf1ique-anular-\xedndice","Alterna picking: down-up-down-up consistentemente","Sincroniza mano derecha e izquierda perfectamente","Graba: debe sonar uniforme, no entrecortado"]},{step:3,instruction:"Practica patrones de secuencia",duration:6,tempo:"80-100 BPM",tips:["Secuencia ascendente de 4: C-D-E-F, D-E-F-G, E-F-G-A...","Secuencia de 3: C-D-E, D-E-F, E-F-G...","Secuencia de 6: C-D-E-F-G-A, D-E-F-G-A-B...","Cada secuencia entrena coordinaci\xf3n diferente","Practica cada secuencia en bucle hasta dominar"]},{step:4,instruction:"Aumenta velocidad gradualmente",duration:4,tempo:"100-140 BPM",tips:["Sube 5 BPM cada vez que domines un tempo","Meta: 120-140 BPM con claridad perfecta","Si pierdes precisi\xf3n, baja el tempo","Velocidad sin control no sirve","Este patr\xf3n es usado en shred/fusion: Paul Gilbert, Greg Howe"]}],progression:"Cualquier escala de 7 notas",evaluation:["\xbfCada nota suena clara sin buzz o muted?","\xbfEl timing es uniforme incluso a alta velocidad?","\xbfPuedo tocar la escala sin mirar el diapas\xf3n?","\xbfLa t\xe9cnica se mantiene relajada?"],nextSteps:"Aplica este patr\xf3n a TODAS las escalas: modos, menor mel\xf3dica, alterada, etc."},{id:"scale-interval-training",title:"Entrenamiento por Intervalos en Escala",category:"technique",level:"beginner",duration:15,goal:"Desarrollar o\xeddo interno y navegaci\xf3n del diapas\xf3n practicando intervalos espec\xedficos",setup:["Una escala (ej: G Mayor)","Metr\xf3nomo a 80 BPM","Conocimiento de intervalos b\xe1sicos"],steps:[{step:1,instruction:"Practica 3ras diat\xf3nicas",duration:4,tempo:"80 BPM",tips:["G-B, A-C, B-D, C-E, D-F#, E-G, F#-A","Ascendente y descendente","Escucha el sonido de cada 3ra","Algunas son mayores (4 semitonos), otras menores (3 semitonos)","Esto entrena o\xeddo para diferenciar cualidades"]},{step:2,instruction:"Practica 4tas diat\xf3nicas",duration:4,tips:["G-C, A-D, B-E, C-F#, D-G, E-A, F#-B","Nota: C-F# es una 4ta aumentada (tritono)","Todas las dem\xe1s son 4tas justas","Identifica el tritono por su sonido \xfanico","Practica en diferentes posiciones del diapas\xf3n"]},{step:3,instruction:"Practica 5tas, 6tas y 7mas",duration:4,tips:["5tas: G-D, A-E, B-F#, etc.","6tas: G-E, A-F#, B-G, etc.","7mas: G-F#, A-G, B-A, etc.","Cada intervalo tiene su propio color","Memoriza el sonido de cada uno"]},{step:4,instruction:"Crea patrones combinando intervalos",duration:3,tips:["Patr\xf3n: 3ra arriba, 2da abajo - G-B-A, A-C-B, B-D-C...","Patr\xf3n: 4ta arriba, 3ra abajo - G-C-A, A-D-B...","Inventa tus propios patrones","Esto es la base de l\xedneas mel\xf3dicas interesantes"]}],progression:"Cualquier escala diat\xf3nica",evaluation:["\xbfPuedo identificar cada intervalo por sonido?","\xbfPuedo tocar cualquier intervalo desde cualquier nota?","\xbfNavego el diapas\xf3n con confianza?"],nextSteps:"Practica intervalos en escalas m\xe1s complejas: menor mel\xf3dica, alterada, disminuida"},{id:"scale-lateral-shifting",title:"Desplazamientos Laterales en Escalas",category:"technique",level:"intermediate",duration:20,goal:"Dominar el movimiento horizontal por el diapas\xf3n manteniendo la misma escala",setup:["Una escala (ej: A D\xf3rico)","Metr\xf3nomo a 70 BPM","Conocimiento de 3+ posiciones de la escala"],steps:[{step:1,instruction:"Identifica 3 posiciones de la misma escala",duration:5,tips:["Posici\xf3n 1: trastes 5-8","Posici\xf3n 2: trastes 10-13","Posici\xf3n 3: trastes 15-17","Todas tocan la misma escala A D\xf3rico","Dibuja o visualiza mentalmente cada posici\xf3n"]},{step:2,instruction:"Practica desplazamiento suave entre posiciones",duration:7,tempo:"70 BPM",tips:["Empieza en posici\xf3n 1, toca 4 notas","Despl\xe1zate a posici\xf3n 2, contin\xfaa la escala","Despl\xe1zate a posici\xf3n 3, contin\xfaa",'Usa notas "pivot" - notas compartidas entre posiciones',"El desplazamiento debe ser imperceptible al o\xeddo","Usa deslizamientos (slides) para suavizar transiciones"]},{step:3,instruction:"Crea l\xedneas que crucen todo el diapas\xf3n",duration:5,tempo:"80 BPM",tips:["Empieza en traste 5, termina en traste 17","Solo notas de la escala, pero m\xe1ximo rango","Esto crea l\xedneas dram\xe1ticas con amplio registro","T\xe9cnica de Michael Brecker, John Coltrane","Practica ascendente y descendente"]},{step:4,instruction:"Improvisa usando desplazamientos intencionales",duration:3,tips:["No te quedes en una posici\xf3n c\xf3moda","Fuerza cambios de posici\xf3n cada 4-8 notas","Resultado: l\xedneas m\xe1s variadas y menos predecibles","Graba y escucha: debe sonar fluido, no entrecortado"]}],progression:"Modal vamp en la tonalidad de tu escala",evaluation:["\xbfLos desplazamientos son suaves y silenciosos?","\xbfPuedo navegar todo el diapas\xf3n sin pensar?","\xbfMis l\xedneas usan el rango completo del instrumento?"],nextSteps:"Practica desplazamientos en cambios r\xe1pidos: ii-V-I donde cada acorde est\xe1 en posici\xf3n diferente"},{id:"scale-chromatic-integration",title:"Integraci\xf3n de Cromatismo en Escalas",category:"technique",level:"intermediate",duration:20,goal:"A\xf1adir notas crom\xe1ticas a escalas diat\xf3nicas para crear l\xedneas m\xe1s sofisticadas",setup:["Una escala base (ej: C Jonio/Mayor)","Metr\xf3nomo a 90 BPM","Conocimiento de approach notes"],steps:[{step:1,instruction:"Practica aproximaciones crom\xe1ticas desde abajo",duration:5,tempo:"90 BPM",tips:["Para llegar a C: toca B-C (aproximaci\xf3n crom\xe1tica)","Para llegar a E: toca D#-E","Para llegar a G: toca F#-G","A\xf1ade medio tono antes de cada nota target","Esto suena jazzy y sofisticado inmediatamente"]},{step:2,instruction:"Practica aproximaciones desde arriba",duration:5,tips:["Para C: toca Db-C","Para E: toca F-E","Para G: toca Ab-G","Aproximaci\xf3n desde arriba tiene sabor diferente","Menos com\xfan que desde abajo - sorprende m\xe1s"]},{step:3,instruction:"Practica enclosures (rodeamiento crom\xe1tico)",duration:6,tips:["Para llegar a C: B-Db-C (desde abajo y arriba)","O Db-B-C (desde arriba y abajo)","Rodea la target note completamente","Sonido super bebop - Charlie Parker usaba esto constantemente","Target notes deben caer en beats fuertes"]},{step:4,instruction:"Improvisa mezclando escala + cromatismo",duration:4,tempo:"100 BPM",tips:["Base: escala diat\xf3nica (inside)","Decoraci\xf3n: aproximaciones crom\xe1ticas","Formula: 70% diat\xf3nico, 30% crom\xe1tico","El cromatismo debe sonar intencional, no como errores","Graba y analiza: \xbfsuena jazz profesional?"]}],progression:"Backing track simple (blues, ii-V-I)",evaluation:["\xbfEl cromatismo embellece sin oscurecer la armon\xeda?","\xbfLas aproximaciones resuelven limpiamente?","\xbfSuena como bebop profesional?"],nextSteps:"Transcribe 16 compases de Charlie Parker - analiza su uso de cromatismo en detalle"},{id:"scale-sequence-patterns",title:"Patrones de Secuencia en Escalas",category:"technique",level:"beginner",duration:15,goal:"Desarrollar coordinaci\xf3n y visualizaci\xf3n usando secuencias num\xe9ricas en escalas",setup:["Una escala de 7 notas","Metr\xf3nomo a 80 BPM","Papel para anotar patrones"],steps:[{step:1,instruction:"Secuencia de 4 notas ascendente",duration:4,tempo:"80 BPM",tips:["Numeramos la escala: 1-2-3-4-5-6-7-8","Patr\xf3n: 1-2-3-4, 2-3-4-5, 3-4-5-6, 4-5-6-7, etc.","C Mayor: C-D-E-F, D-E-F-G, E-F-G-A, F-G-A-B...","Practica hasta que sea autom\xe1tico","Este patr\xf3n aparece en Bach, Mozart, y bebop"]},{step:2,instruction:"Secuencia de 3 notas",duration:4,tips:["Patr\xf3n: 1-2-3, 2-3-4, 3-4-5, 4-5-6...","C Mayor: C-D-E, D-E-F, E-F-G, F-G-A...","Crea l\xedneas m\xe1s angulares","Prueba variaciones r\xedtmicas: tresillos, corcheas, semicorcheas"]},{step:3,instruction:"Secuencias con saltos",duration:4,tips:["Patr\xf3n skip: 1-3, 2-4, 3-5, 4-6... (solo 3ras)","Patr\xf3n 4tas: 1-4, 2-5, 3-6, 4-7...","Patr\xf3n mixto: 1-2-4, 2-3-5, 3-4-6...","Cada patr\xf3n entrena diferentes saltos","\xdatil para construir vocabulario de intervalos"]},{step:4,instruction:"Inventa tus propias secuencias",duration:3,tips:["Patr\xf3n reversa: 4-3-2-1, 5-4-3-2...","Patr\xf3n c\xedclico: 1-3-2-4, 2-4-3-5...","Infinitas posibilidades","Anota las que suenan interesantes","Cada secuencia puede convertirse en un lick"]}],progression:"Practicar sin backing track primero",evaluation:["\xbfPuedo ejecutar cada secuencia sin errores?","\xbfEntiendo el patr\xf3n num\xe9rico?","\xbfPuedo aplicar la misma secuencia a diferentes escalas?"],nextSteps:"Usa estas secuencias como base de improvisaci\xf3n - transf\xf3rmalas con ritmo y din\xe1mica"},{id:"scale-modal-mixture",title:"Mezcla Modal en Escalas",category:"technique",level:"advanced",duration:25,goal:"Combinar notas de diferentes modos sobre el mismo centro tonal",setup:["Backing track de vamp en C","Conocimiento de modos de Mayor","Metr\xf3nomo opcional"],steps:[{step:1,instruction:"Compara C Jonio (Mayor) vs C Mixolidio",duration:5,tips:["C Jonio: C-D-E-F-G-A-B","C Mixolidio: C-D-E-F-G-A-Bb","Diferencia: B vs Bb (7ma Mayor vs b7)","Toca cada escala separadamente","Escucha el cambio de color"]},{step:2,instruction:"Mezcla ambos modos en una l\xednea",duration:8,tips:["Comp\xe1s 1: C Jonio con B natural","Comp\xe1s 2: C Mixolidio con Bb","Alterna entre ambas 7mas","Esto crea tensi\xf3n/release interesante","Com\xfan en rock progresivo y fusion"]},{step:3,instruction:"A\xf1ade m\xe1s modos: C Lidio y C D\xf3rico",duration:7,tips:["C Lidio: a\xf1ade F# (#11) - sonido brillante","C D\xf3rico (menos com\xfan sobre C): Eb, Bb","Ahora tienes: B, Bb (de Mixo), F# (de Lidio)","Mezcla todas estas alteraciones","Sonido muy contempor\xe1neo - jazz moderno"]},{step:4,instruction:"Improvisa usando mixture modal libremente",duration:5,tips:["Centro tonal: C","Escala base: C Mayor","Alteraciones permitidas: Bb, F#, Eb","Cambia alteraciones seg\xfan feeling","Esto es outside controlado","Ejemplos: Frank Zappa, Allan Holdsworth"]}],progression:"Vamp en C (o cualquier centro tonal)",evaluation:["\xbfMantengo el centro tonal claro?","\xbfLas alteraciones suenan intencionales?","\xbfCreo contraste entre secciones?","\xbfSuena contempor\xe1neo y sofisticado?"],nextSteps:'Estudia "Peaches en Regalia" de Frank Zappa - master class de modal mixture'},{id:"scale-speed-builder",title:"Constructor de Velocidad en Escalas",category:"technique",level:"advanced",duration:30,goal:"Desarrollar velocidad extrema manteniendo claridad y precisi\xf3n",setup:["Una escala dominada (ej: E menor pentat\xf3nica o A D\xf3rico)","Metr\xf3nomo con subdivisi\xf3n audible","Grabadora para verificar claridad"],steps:[{step:1,instruction:"Establece tu baseline de velocidad c\xf3moda",duration:5,tempo:"60-100 BPM",tips:["Toca la escala en corcheas","Encuentra el tempo donde puedes tocar 10 veces sin error","Anota este tempo - es tu punto de partida","No hay verg\xfcenza si es lento - todos empezamos ah\xed","Ejemplo: si es 80 BPM, est\xe1 perfecto"]},{step:2,instruction:"Pr\xe1ctica de sprint: 10 segundos m\xe1xima velocidad",duration:10,tips:["Toca la escala lo m\xe1s r\xe1pido posible durante 10 segundos","Descansa 20 segundos","Repite 10 veces","No importa si hay errores - empuja los l\xedmites","Este m\xe9todo desarrolla velocidad explosiva","T\xe9cnica de athletes aplicada a m\xfasica"]},{step:3,instruction:"Incremento gradual: m\xe9todo 5-10-15",duration:10,tempo:"Variable",tips:["Toca a tu tempo base durante 5 minutos","Sube 10 BPM, toca 10 minutos","Si dominas, sube otros 10 BPM","Si fallas m\xe1s de 3 veces, baja 5 BPM","Objetivo: aumentar 10-20 BPM por semana","Paciencia - velocidad real toma meses, no d\xedas"]},{step:4,instruction:"Verificaci\xf3n de claridad",duration:5,tips:["GRABA tu playing a alta velocidad","Escucha: \xbfcada nota es clara?","Si hay notas fantasma, buzz, o muting accidental → BAJA TEMPO","Velocidad sin claridad = basura","La meta es velocidad USABLE, no solo r\xe1pido","Ejemplo: Paul Gilbert es r\xe1pido Y claro"]}],progression:"Solo con metr\xf3nomo inicialmente",evaluation:["\xbfPuedo mantener la velocidad alta por 30+ segundos?","\xbfCada nota es audible y clara?","\xbfLa t\xe9cnica se mantiene relajada?","\xbfHe aumentado mi velocidad base?"],nextSteps:"Aplica esta metodolog\xeda a licks, arpegios, y frases completas - no solo escalas"},{id:"scale-string-skipping",title:"Salto de Cuerdas en Escalas",category:"technique",level:"advanced",duration:20,goal:"Dominar t\xe9cnica de string-skipping para crear l\xedneas con saltos de octava",setup:["Una escala (ej: G Mayor)","Metr\xf3nomo a 70 BPM","Enfoque en mano derecha/picking"],steps:[{step:1,instruction:"Practica saltos simples: una cuerda",duration:5,tempo:"70 BPM",tips:["Toca en cuerda E, salta a cuerda D (salta cuerda A)","Ejemplo: G en E grave → B en D","Picking alterno: down-up incluso cuando saltas","La cuerda intermedia NO debe sonar","Control de mano derecha es cr\xedtico"]},{step:2,instruction:"Secuencia con string-skipping",duration:7,tips:["Patr\xf3n: nota en E, nota en D, nota en E, nota en D...","G(E)-B(D)-A(E)-C(D)-B(E)-D(D)-C(E)-E(D)...","Crea textura angular y moderna","M\xe1s dif\xedcil que escala regular pero suena \xfanico","Usado por Steve Vai, Frank Gambale"]},{step:3,instruction:"Saltos de 2 cuerdas",duration:5,tips:["Toca en E grave, salta a G (2 cuerdas)","Incluso m\xe1s desafiante","Silencia las cuerdas intermedias con ambas manos","Practica LENTO primero","Claridad > velocidad"]},{step:4,instruction:"Crea licks usando string-skipping",duration:3,tips:["Combina string-skipping con escala normal","Ejemplo: 4 notas normal, 4 notas con skipping","Esto hace tus l\xedneas menos predecibles","Sonido signature de guitarra shred","Graba: debe sonar limpio sin cuerdas fantasma"]}],progression:"Modal vamp o practice sin backing track",evaluation:["\xbfControlo qu\xe9 cuerdas suenan y cu\xe1les no?","\xbfNo hay cuerdas fantasma o buzz?","\xbfPuedo usar string-skipping musicalmente?"],nextSteps:"Integra string-skipping en arpegios - a\xfan m\xe1s efectivo que en escalas"},{id:"scale-rhythmic-variations",title:"Variaciones R\xedtmicas de Escalas",category:"technique",level:"intermediate",duration:20,goal:"Transformar escalas aburridas en material mel\xf3dico interesante usando ritmo",setup:["Una escala memorizada","Metr\xf3nomo a 100 BPM","Mentalidad: el ritmo es tan importante como las notas"],steps:[{step:1,instruction:"Practica en negras, corcheas, tresillos, semicorcheas",duration:6,tempo:"100 BPM",tips:["Negras: 1 nota por beat","Corcheas: 2 notas por beat","Tresillos: 3 notas por beat","Semicorcheas: 4 notas por beat","Misma escala, 4 velocidades diferentes","Domina cada subdivisi\xf3n antes de mezclar"]},{step:2,instruction:"Mezcla subdivisiones en una frase",duration:6,tips:["Comp\xe1s 1: negras","Comp\xe1s 2: corcheas","Comp\xe1s 3: tresillos","Comp\xe1s 4: semicorcheas","Esto crea aceleraci\xf3n dram\xe1tica","Prueba tambi\xe9n deceleraci\xf3n (inverso)"]},{step:3,instruction:"A\xf1ade silencios (rests)",duration:5,tips:["Toca 3 notas, silencio de 1 beat","Toca 5 notas, silencio de 2 beats","Los silencios son tan importantes como las notas","Esto hace la escala sonar como melod\xeda","Miles Davis: \"It's not the notes you play, it's the notes you don't play\""]},{step:4,instruction:"Crea patrones r\xedtmicos espec\xedficos",duration:3,tips:["Patr\xf3n jazz: corchea-tresillo-corchea","Patr\xf3n funk: corta-larga-corta-larga (staccato-legato)","Patr\xf3n rock: galopante (negra-corchea-corchea)","El ritmo define el estilo m\xe1s que las notas","Misma escala suena blues, jazz, o rock seg\xfan ritmo"]}],progression:"Backing track de cualquier estilo",evaluation:["\xbfControlo diferentes subdivisiones?","\xbfUso silencios efectivamente?","\xbfLa escala suena musical en vez de ejercicio?",'\xbfPuedo tocar en el "pocket" de diferentes estilos?'],nextSteps:"Estudia fraseo r\xedtmico de Sonny Rollins - master del ritmo en melod\xeda"},{id:"transcription-integration",title:"Integraci\xf3n de Material Transcrito",category:"ear",level:"advanced",duration:30,goal:"Incorporar licks transcritos en tu vocabulario org\xe1nicamente",setup:["5-10 licks transcritos de un solo de Charlie Parker o similar","Backing track del tune original","Los licks escritos y memorizados"],steps:[{step:1,instruction:"Transporta cada lick a todas las 12 tonalidades",duration:10,tips:["Lick 1 en C, luego Db, D, Eb, E, F, etc.","Toca lentamente hasta dominar cada tonalidad","Usa metr\xf3nomo - mant\xe9n timing consistente","Esto es tedioso pero ESENCIAL","Sin esto, solo puedes usar el lick en una tonalidad","Pr\xe1ctica diaria: 1 lick en 12 keys"]},{step:2,instruction:"Identifica el contexto arm\xf3nico de cada lick",duration:5,tips:["\xbfSobre qu\xe9 tipo de acorde funciona?","ii-V? Solo V7? Solo I? Modal?","Ejemplo: lick Parker usa sobre G7 → Cmaj7","Ese lick funcionar\xe1 sobre CUALQUIER V7 → I","Transporta a otros contextos arm\xf3nicos","Lick se vuelve herramienta, no solo quote"]},{step:3,instruction:'Practica "insertar" licks en tus improvisaciones',duration:8,tips:["Improvisa normalmente","Cuando llegue el contexto correcto, usa el lick","Primera vez ser\xe1 obvio y forzado - OK","Con pr\xe1ctica se integra naturalmente",'El lick debe sonar como "tu" idea, no como quote',"Trabaja CADA lick hasta que sea autom\xe1tico"]},{step:4,instruction:"Var\xeda los licks - hazlos tuyos",duration:7,tips:["Cambia el ritmo del lick","Usa solo la primera mitad","Combina mitades de diferentes licks","A\xf1ade cromatismo extra","Transpone internamente","Ahora no es el lick de Parker - es TU lick inspirado en Parker","Este es el proceso de desarrollar voz propia"]}],progression:"Standard donde originalmente transcribiste",evaluation:["\xbfPuedo tocar cada lick en todas las tonalidades?","\xbfLos licks suenan naturales en mi improvisaci\xf3n?","\xbfHe variado los licks para hacerlos m\xedos?","\xbfAmpli\xf3 mi vocabulario o solo memoric\xe9 patterns?"],nextSteps:"Continuar transcribiendo - cada m\xfasico debe transcribir 100+ solos m\xednimo"},{id:"advanced-comping-integration",title:"Comping Avanzado Durante Solos",category:"integration",level:"advanced",duration:25,goal:"Acompa\xf1arte a ti mismo mientras improvises (t\xe9cnica solo guitar/piano)",setup:["Backing track opcional (o solo t\xfa)","Conocimiento de voicings complejos","Habilidad de tocar acordes y melod\xeda simult\xe1neamente"],steps:[{step:1,instruction:"Practica voicings en medio del diapas\xf3n que permiten melod\xeda encima",duration:8,tips:["Guitarristas: voicings en cuerdas 4-2, melod\xeda en cuerda 1","Pianistas: acordes con mano izquierda, melod\xeda con derecha","Voicings deben ser completos pero no ocupar TODO el espacio","Practica cambios de acordes con estos voicings","Debe ser autom\xe1tico antes de a\xf1adir melod\xeda"]},{step:2,instruction:"Comping en beats 2 y 4, melod\xeda en beats 1 y 3",duration:7,tips:["Beat 1: nota melod\xeda","Beat 2: chunk del acorde","Beat 3: nota melod\xeda","Beat 4: chunk del acorde","Esto crea interlock entre comping y melod\xeda","Ritmo t\xedpico de stride piano o jazz guitar solo","Practica LENTAMENTE primero"]},{step:3,instruction:"Improvisa l\xednea mel\xf3dica mientras mantienes comping",duration:6,tips:["No detengas el comping para hacer melod\xeda compleja","Simplifica melod\xeda si es necesario","El comping establece armon\xeda, melod\xeda a\xf1ade color","Balance es clave - ni todo armon\xeda ni todo melod\xeda","Escucha a Joe Pass, Tuck Andress (guitarra)","O Bill Evans, Art Tatum (piano)"]},{step:4,instruction:"Crea texturas variadas alternando densidad arm\xf3nica",duration:4,tips:["Secci\xf3n A: comping denso (acordes cada 2 beats)","Secci\xf3n B: comping sparse (acordes cada 4-8 beats)","Secci\xf3n C: solo melod\xeda sin acordes (implica armon\xeda)","Secci\xf3n D: acordes sin melod\xeda","Esto crea arquitectura din\xe1mica en tu solo","Cada textura tiene prop\xf3sito expresivo"]}],progression:"Cualquier standard - eventualmente sin backing track",evaluation:["\xbfMantengo independencia entre melod\xeda y comping?","\xbfEl comping es r\xedtmicamente interesante?","\xbfLa armon\xeda est\xe1 clara?","\xbfSuena como una performance completa o secciones separadas?"],nextSteps:"Meta final: tocar standards completos solo, sin backing track"},{id:"thematic-improvisation",title:"Improvisaci\xf3n Tem\xe1tica Narrativa",category:"integration",level:"advanced",duration:30,goal:'Crear solos que cuenten una "historia" con inicio, desarrollo y conclusi\xf3n',setup:["Backing track de standard o blues","Mentalidad de storytelling","Sin restricciones t\xe9cnicas - solo narrativa"],steps:[{step:1,instruction:'Define 3 "cap\xedtulos" para tu solo antes de empezar',duration:5,tips:["Cap\xedtulo 1 (introducci\xf3n): simple, establece tema","Cap\xedtulo 2 (desarrollo): explora y expande","Cap\xedtulo 3 (cl\xedmax y resoluci\xf3n): m\xe1xima intensidad → calma","Piensa arquitectura antes de improvisar","Como escribir novela vs stream of consciousness"]},{step:2,instruction:"Chorus 1-2: Introducci\xf3n - establece material tem\xe1tico",duration:7,tips:["Presenta 1-2 motivos simples","NO muestres todo tu vocabulario todav\xeda","Deja espacio - menos es m\xe1s","Registro medio, din\xe1mica moderada","Como introducir personajes en una pel\xedcula",'Audience debe sentir que "hay m\xe1s por venir"']},{step:3,instruction:"Chorus 3-5: Desarrollo - explora y transforma el material",duration:10,tips:["Toma los motivos del intro y des\xe1rrollalos","Usa todas las t\xe9cnicas: transposici\xf3n, inversi\xf3n, fragmentaci\xf3n","Aumenta densidad gradualmente","Sube de registro poco a poco","Incrementa din\xe1mica progresivamente","Introduce cromatismo y t\xe9cnicas outside","Construcci\xf3n de tensi\xf3n hacia cl\xedmax"]},{step:4,instruction:"Chorus 6-7: Cl\xedmax y Resoluci\xf3n",duration:8,tips:["Chorus 6: m\xe1xima intensidad","- Registro m\xe1s agudo","- M\xe1xima densidad","- Fortissimo din\xe1mico","- T\xe9cnicas m\xe1s outside","Chorus 7: resoluci\xf3n","- Vuelve a registro medio","- Simplifica","- Disminuye din\xe1mica","- Referencia el motivo inicial (cierre circular)","- Finaliza en nota conclusiva, probablemente t\xf3nica","Como resolver todos los conflictos al final de pel\xedcula"]}],progression:"Cualquier standard o forma blues",evaluation:["\xbfMi solo tiene arco narrativo claro?","\xbfPuedo escuchar inicio, desarrollo y conclusi\xf3n?","\xbfHay sentido de viaje, no solo serie de licks?","\xbfEl cl\xedmax est\xe1 en el lugar correcto?","\xbfLa resoluci\xf3n se siente satisfactoria?","\xbfCont\xf3 una historia musical?"],nextSteps:'Analiza arquitectura de solos hist\xf3ricos: Coltrane "Giant Steps" (versi\xf3n album) - perfecci\xf3n narrativa'}]}}]);